import { readFileSync } from 'node:fs';

// stdin: {"inputs": {}, "dependencies": {"audit": {"text": ..., "data": {...}}}, "step": {"id", "name"}}
const input = JSON.parse(readFileSync(0, 'utf8'));
const names = (input.dependencies.audit?.data?.dependencies ?? []).map((entry) => String(entry).trim().split(/\s+/)[0]);
const duplicates = [...new Set(names.filter((name, index) => names.indexOf(name) !== index))];
// One JSON object on stdout is the step result, checked against resultFields.
console.log(JSON.stringify({ total: names.length, duplicates }));
